// ============================================
// STEP 1: Get Input Data
// ============================================

// Get all RSS articles from the previous node (RSS Feed Read)
// This will be ~280 articles from all 14 feeds
const allItems = $input.all();

// Get the feed information from Google Sheets
// This references the "Get Active RSS Feeds" node
const feedsNode = $('Get Active RSS Feeds').all();

// ============================================
// STEP 2: Create Feed URL to Name Mapping
// ============================================

// Create a Map (like a dictionary) to quickly look up feed names
// Map structure: { "feed_url" => "feed_name" }
const feedMap = new Map();
feedsNode.forEach(feed => {
  feedMap.set(feed.json.feed_url, feed.json.feed_name);
});

// Example feedMap after this:
// "https://dev.to/feed/tag/testing" => "DEV - Testing"
// "https://automationpanda.com/feed/" => "Automation Panda"

// ============================================
// STEP 3: Process Each Article
// ============================================

// Loop through each article and format it for AI
const articles = allItems.map((item, index) => {
  const data = item.json;

  // Start with a default source name
  let sourceName = 'Unknown Source';

  // ============================================
  // LEVEL 1: Try to match article domain with feed domain
  // ============================================

  if (data.link) {
    // Loop through our feed map to find a match
    for (const [feedUrl, feedName] of feedMap) {
      try {
        // Extract domain from article link
        // Example: "https://dev.to/article" -> split by '/' -> ['https:', '', 'dev.to', 'article']
        // Index [2] gives us 'dev.to'
        const articleDomain = data.link.split('/')[2];

        // Extract domain from feed URL
        const feedDomain = feedUrl.split('/')[2];

        // If domains match, we found the source!
        if (articleDomain === feedDomain) {
          sourceName = feedName; // Use the name from Google Sheet
          break; // Stop searching, we found it
        }
      } catch (e) {
        // If any error (malformed URL), just skip and continue
      }
    }
  }

  // ============================================
  // LEVEL 2: Try using RSS creator field
  // Some RSS feeds include author/creator information
  // ============================================

  if (sourceName === 'Unknown Source' && data.creator) {
    sourceName = data.creator; // Use creator name (e.g., "John Doe")
  }

  // ============================================
  // LEVEL 3: Smart domain extraction as last resort
  // Convert domain name to readable format
  // ============================================

  if (sourceName === 'Unknown Source' && data.link) {
    try {
      // Extract domain from link
      const domain = data.link.split('/')[2];

      // Clean up and format the domain name
      // Example: "automation-panda.com" -> "Automation Panda"
      sourceName = domain
        .replace('www.', '')        // Remove www
        .replace('.com', '')        // Remove .com
        .replace('.io', '')         // Remove .io
        .replace('.dev', '')        // Remove .dev
        .replace('.org', '')        // Remove .org
        .split('.')[0]              // Get first part (before any remaining dots)
        .split('-')                 // Split by hyphens
        .map(word => word.charAt(0).toUpperCase() + word.slice(1)) // Capitalize each word
        .join(' ');                 // Join with spaces
    } catch (e) {
      // If everything fails, use this generic name
      sourceName = 'Testing Blog';
    }
  }

  // ============================================
  // STEP 4: Return cleaned article object
  // ============================================

  return {
    index: index,                                                          // Article position (0, 1, 2...)
    title: data.title || 'No title',                                      // Use title or fallback
    link: data.link || data.url || '',                                    // Use link or url field or empty
    description: data.contentSnippet || data.description || 'No description', // Article summary
    pubDate: data.pubDate || data.isoDate || '',                          // Publication date
    source: sourceName                                                     // Source name we determined above
  };
});

// ============================================
// STEP 5: Create AI Prompt
// ============================================

// Build a detailed prompt asking AI to select the best 15 articles
const prompt = `You are a QA/Testing news curator specializing in software testing and quality assurance. Below are ${articles.length} articles from various testing blogs and communities.
Select the TOP 15 most relevant and valuable articles for QA professionals and test automation engineers. Prioritize:
1. AI/ML in testing (highest priority)
2. Latest automation frameworks (Playwright, Selenium, Cypress, WebdriverIO)
3. Testing best practices and methodologies
4. Industry trends and innovations in QA
5. Practical tutorials and hands-on guides
6. New testing tools and tool comparisons
7. CI/CD and DevOps testing practices
Avoid:
- Sales/marketing content
- Outdated articles (older than 1 week)
- Duplicate or very similar topics
- Generic software development content not focused on testing
Articles:
${articles.map((a, i) => `
${i + 1}. Title: ${a.title}
   Source: ${a.source}
   Published: ${a.pubDate}
   Description: ${a.description}
`).join('\n')}
Respond ONLY with a JSON array containing the indices of the 15 best articles (0-based indexing). 
Example format:
[0, 5, 12, 18, 23, 30, 35, 40, 45, 50, 55, 60, 65, 70, 75]
CRITICAL RULES:
- Output ONLY the JSON array with exactly 15 numbers
- No markdown code blocks
- No explanations or additional text
- No \`\`\`json formatting
- Just the raw array`;

// ============================================
// STEP 6: Return the result
// ============================================

// Return ONE item containing:
// - articles: Array of all cleaned articles
// - prompt: The text to send to AI
return [{
  json: {
    articles: articles,
    prompt: prompt
  }
}];

// ============================================
// WHAT HAPPENS NEXT:
// This output goes to the AI Agent node which:
// 1. Receives the prompt
// 2. Sends it to Google Gemini
// 3. Gemini returns array like [0, 5, 12, 18, 23...]
// 4. Next node extracts those specific articles
// ============

// ============================================
// STEP 1: Get the AI response
// ============================================

// Get the AI's output (the array of indices)
const aiResponse = $input.first().json;

// ============================================
// STEP 2: Get the original articles list
// ============================================

// Get all articles from the "Format Articles for AI" node
// IMPORTANT: Make sure this matches your actual node name!
const formatNode = $('Format Articles for AI').first().json;
const allArticles = formatNode.articles;

// ============================================
// STEP 3: Parse the AI response
// ============================================

// Extract the selected indices from AI response
let selectedIndices = [];
try {
  // The AI response might be in different fields
  const responseText = aiResponse.output || aiResponse.text || aiResponse.response || '';

  // Parse the JSON array
  selectedIndices = JSON.parse(responseText.trim());

  console.log('AI selected indices:', selectedIndices);
} catch (error) {
  // If parsing fails, use first 5 articles as fallback
  console.log('Error parsing AI response:', error);
  selectedIndices = [0, 1, 2, 3, 4];
}

// ============================================
// STEP 4: Get the actual articles by their indices
// ============================================

// Filter to get only the articles AI selected
const selectedArticles = selectedIndices
  .filter(i => i >= 0 && i < allArticles.length) // Make sure index is valid
  .map(i => allArticles[i]);                     // Get the article at that index

console.log(`AI selected ${selectedIndices.length} articles`);
console.log(`Valid articles found: ${selectedArticles.length}`);

// ============================================
// STEP 5: Return the selected articles
// ============================================

return [{
  json: {
    selected_articles: selectedArticles,     // The 15 articles AI chose
    selected_count: selectedArticles.length, // Count (should be 15)
    original_indices: selectedIndices        // The indices AI returned
  }
}];

// ============================================
// WHAT HAPPENS NEXT:
// These 15 selected articles go to the next node
// ============================================

// Get all subscribers
const subscribers = $input.all();

// Filter only active subscribers
const eligibleSubscribers = subscribers.filter(subscriber => {
  const data = subscriber.json;

  // Check if active column is TRUE
  // Handle both boolean and string values
  const isActive = data.active === true || 
                   data.active === 'TRUE' || 
                   data.active === 'true';

  return isActive;
});

// If no subscribers, stop
if (eligibleSubscribers.length === 0) {
  return [{
    json: {
      has_subscribers: false,
      message: 'No active subscribers found'
    }
  }];
}

// Return eligible subscribers
return [{
  json: {
    has_subscribers: true,
    subscriber_count: eligibleSubscribers.length,
    subscribers: eligibleSubscribers.map(s => ({
      chat_id: s.json.chat_id,
      username: s.json.username
    }))
  }
}];

// ============================================
// STEP 1: Get the articles selected by AI
// ============================================

// Get the output from "Parse AI Response" node
// Use .first() to explicitly get the first (and only) item
const selectedArticlesNode = $('Parse AI Response').first().json;
const allSelectedArticles = selectedArticlesNode.selected_articles;

// Take only the first 5 articles from AI's selection
// const articles = allSelectedArticles.slice(0, 5);
const articles = allSelectedArticles
  .filter(article =>
    article &&
    article.title &&
    article.link
  )
  .slice(0, 5);

// ============================================
// STEP 2: Get the list of subscribers
// ============================================

// Get the output from "Filter Active Subscribers" node
// Use .first() to explicitly get the first (and only) item
const subscribersData = $('Filter Active Subscribers').first().json;
const subscribers = subscribersData.subscribers;

// ============================================
// STEP 3: Handle case when no articles found
// ============================================

if (!articles || articles.length === 0) {
  return subscribers.map(subscriber => ({
    json: {
      has_articles: false,
      message: "📰 No new testing news today!",
      chat_id: subscriber.chat_id,
      username: subscriber.username
    }
  }));
}

// ============================================
// STEP 4: Build the digest message in HTML format
// ============================================

let digest = '📰 <b>BriefFlow AI — Personalized Morning News Digest</b>\n\n';
//digest += '<i>🤖 Curated by AI from top testing blogs</i>\n\n';
digest += `Found <b>${articles.length}</b> article${articles.length > 1 ? 's' : ''} for you:\n\n`;

// ============================================
// STEP 5: Add each article to the digest
// ============================================

articles.forEach((article, index) => {
  digest += `${index + 1}. <b>${article.title}</b>\n`;
  digest += `   📍 ${article.source}\n`;
  digest += `   🔗 <a href="${article.link}">Read article</a>\n\n`;
});

// ============================================
// STEP 6: Add footer to the digest
// ============================================

digest += '\n---\n';
digest += '<i>💡 Powered by Arifuzzaman</i>';

// ============================================
// STEP 7: Create one output item per subscriber
// ============================================

return subscribers.map(subscriber => ({
  json: {
    has_articles: true,
    digest: digest,
    article_count: articles.length,
    chat_id: subscriber.chat_id,
    username: subscriber.username
  }
}));
